import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"생애최초로 주택청약 해보기","description":"","frontmatter":{"title":"생애최초로 주택청약 해보기","date":"2026-05-26T07:33+09:00","tags":["민영주택청약","생애최초 특별공급"]},"headers":[],"relativePath":"sleep/housing.md","filePath":"sleep/housing.md","lastUpdated":1785935908000}`),a={name:`sleep/housing.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="생애최초로-주택청약-해보기" tabindex="-1">생애최초로 주택청약 해보기 <a class="header-anchor" href="#생애최초로-주택청약-해보기" aria-label="Permalink to “생애최초로 주택청약 해보기”">​</a></h1><p>2029년 1월 입주 예정인 <mark>경기도 외곽 지역의 민영주택청약</mark> 에 생애최초 특별공급으로 신청했던 이야기를 해보려고 해요. 지금은 세대 분리를 목적으로 다른 지역으로 이사해 살고 있지만, 작년(2025년 4월)에는 당시 거주하던 지역의 민영주택청약 공고를 보고 생애최초 특별공급으로 청약을 신청해서 서류 검수와 계약 체결까지 무사히 완료했었답니다.</p><blockquote><p>현재는 계약 체결을 모두 마치고 중도금 대출이 이루어지고 있어요.</p></blockquote><h2 id="청약-당첨만큼-중요한-부적격-판정-피하기" tabindex="-1">청약 당첨만큼 중요한 &#39;부적격 판정&#39; 피하기 <a class="header-anchor" href="#청약-당첨만큼-중요한-부적격-판정-피하기" aria-label="Permalink to “청약 당첨만큼 중요한 &#39;부적격 판정&#39; 피하기”">​</a></h2><p>주택청약 시 요구 조건 체크와 신청 기준에 따른 증빙 서류는 반드시 청약자가 스스로 확인하고 준비해야 함을 잊지 말아야 해요. 청약 신청 시점에 부적격 여부를 미리 판단해 주는 것이 아니라, 우선 당첨을 진행하고 나서 제출된 서류를 통해 사후에 <strong>부적격 대상자를 판단</strong> 하기 때문이에요. 실제로 매년 주택청약 당첨 후 부적격으로 인해 <a href="https://www.dailiang.co.kr/news/articleView.html?idxno=228407" target="_blank" rel="noreferrer">당첨이 취소되고 일정 기간 청약 신청 기회가 박탈</a>되는 상황이 빈번하게 벌어지고 있어요. 부적격 처리가 되더라도 청약통장 자체가 소멸하는 것은 아니지만, 일정 기간 청약 신청 기회마저 박탈되는 페널티를 받게 되므로 각별히 주의해야 해요.</p><p>민영주택청약의 <a href="https://kbthink.com/main/asset-management/wealth-manage-tip/kbthink-original/202411/first-place.html" target="_blank" rel="noreferrer">일반공급 1순위</a>는 해당 지역, 그리고 기타 지역 순서대로 기회가 주어지며 주택 전용면적에 따라 <strong>가점제와 추첨제</strong> 로 진행돼요. 이때 가장 많이 부적격 사례가 발생하는 원인은 <a href="https://blog.toss.im/article/housing-5" target="_blank" rel="noreferrer">주택청약 신청 시 입력한 가점</a>이 당첨 후 서류로 확인한 <strong>실제 가점</strong> 과 다른 경우라고 해요. 저는 일반공급이 아닌 <strong>생애최초 특별공급</strong> 으로 청약을 신청해서 당첨되어 계약을 체결했는데요. 특별공급을 신청하고자 하신다면 준비해야 할 증빙 서류가 생각보다 정말 많기 때문에, 사전에 제출 서류와 자격 요건을 미리 많이 알아보시는 것이 좋아요.</p><h2 id="생애최초-특별공급을-선택한-이유" tabindex="-1">생애최초 특별공급을 선택한 이유 <a class="header-anchor" href="#생애최초-특별공급을-선택한-이유" aria-label="Permalink to “생애최초 특별공급을 선택한 이유”">​</a></h2><p>지금에서야 해당 공고는 1순위 대상자가 전부 당첨이었다는 사실을 잘 알고 있지만, 당시에는 생애최초 특별공급을 선택할 수밖에 없었어요. 무주택 기간이 길지 않고 부양가족도 없는 저로서는 일반공급의 가점제만으로는 당첨 가능성이 희박하다고 판단했기 때문이에요. 또한 당시에 <strong>세대주(아버지)가 만 60세 이상</strong> 이 되셔서 주택청약 기준상 무주택으로 판정되었기 때문에, 제가 <strong>무주택세대구성원</strong> 으로서 생애최초 특별공급을 신청할 수 있었답니다.</p><p>사실 생애최초 특별공급으로 배정된 세대수가 그리 많지 않은 데다가, 소득 기준도 확인하고 결국 추첨제까지 거쳐야 해서 당첨 가능성이 거의 없다고 생각했어요. 그래서 생애최초 특별공급과 일반공급 1순위 신청을 모두 고려하고 있었죠. 그런데 특별공급 신청 결과를 확인해 보니, <mark>신청자 수가 배정된 세대수보다 적어서</mark> 별도의 추첨 단계를 거치지 않고 <strong>추첨 없이 바로 당첨</strong> 이 되었답니다.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>특별공급에 신청했더라도 당첨 여부가 확실하지 않다면 일반공급으로 중복 신청해도 괜찮아요. 다만, 동일 세대 내에서 중복 청약은 불가능하다는 점만 주의하시면 된답니다.</p></div><h2 id="당첨-이후-부적격-판정을-받을-수-있는-상황들" tabindex="-1">당첨 이후 부적격 판정을 받을 수 있는 상황들 <a class="header-anchor" href="#당첨-이후-부적격-판정을-받을-수-있는-상황들" aria-label="Permalink to “당첨 이후 부적격 판정을 받을 수 있는 상황들”">​</a></h2><p>생애최초 특별공급에 당첨되고 서류 검증 과정에서 부적격 처리되면 생애최초 특별공급 기회는 <mark>당첨 즉시 소멸</mark> 되기 때문에 그 이후로는 다시 신청할 수 없어요. 따라서 특별공급 신청 시에는 검토해야 할 자격 기준이 매우 다양하므로 사전에 꼼꼼히 확인해 두는 것이 좋아요. 먼저 세대주가 만 60세가 넘었더라도 해당 주택을 부모님이 <strong>공동 명의</strong> 로 보유하고 있다면, 주택을 소유 중인 <mark>부모님 모두가 만 60세가 넘어야만</mark> 무주택으로 인정된다는 걸 명심해야 해요. 그리고 부모님의 과거 부동산 소유 이력이 기억만으로는 정확하지 않을 수 있기 때문에, <a href="https://www.iros.go.kr/index.jsp" target="_blank" rel="noreferrer">인터넷등기소</a>를 통해서 <strong>부동산소유현황</strong> 을 미리 조회하여 확인해 보는 것이 좋아요.</p><ul><li>생애최초 특별공급은 등본상 세대구성원 전원이 <mark>과거에 주택을 소유한 이력이 단 한 번도 없어야</mark> 해요.</li><li>주택 공동 명의 여부와 주택 소유자의 만 60세 여부를 꼼꼼히 확인하지 않은 책임은 전적으로 신청자 본인에게 있어요.</li></ul><p>서류 심사 시 제출하는 모든 서류는 <strong>주민등록번호 뒷자리가 반드시 포함</strong> 되어야 해요. 또한 재직증명서나 근로소득원천징수영수증 같은 일부 서류는 복사본이 아닌 <strong>원본</strong> 이어야 하므로, 모집공고와 서류 제출 안내문을 토대로 견본주택(모델하우스) 측에 꼭 직접 문의해 보는 것이 가장 확실해요.</p><blockquote><p>모집공고문과 홈페이지에 별도로 공유된 서류 제출 안내문에 명시된 내용이 서로 다르거나 발급 기준이 애매한 부분이 있어 준비 과정에서 꽤 헷갈리기도 했어요.</p></blockquote><h2 id="단독세대-유무에-따른-미혼-1인-가구-기준" tabindex="-1">단독세대 유무에 따른 미혼 1인 가구 기준 <a class="header-anchor" href="#단독세대-유무에-따른-미혼-1인-가구-기준" aria-label="Permalink to “단독세대 유무에 따른 미혼 1인 가구 기준”">​</a></h2><p>민영주택청약에서 미혼인 <strong>1인 가구</strong> 는 주민등록표등본상의 세대 구성 형태에 따라 <strong>단독세대</strong> 와 <strong>단독세대가 아닌 자</strong> 로 나뉘어요. 이 구분에 따라 신청할 수 있는 주택의 면적 제한이 달라지기 때문에 주의 깊게 살펴보아야 해요.</p><ul><li><strong>단독세대</strong>: 혼자 거주하며 주민등록표등본상 단독 세대주로 되어 있는 경우예요. 이 경우 <strong>전용면적 60㎡ 이하</strong> 의 주택에만 신청할 수 있으므로, 기준을 확인하지 않고 초과 주택에 청약하면 부적격 처리가 돼요.</li><li><strong>단독세대가 아닌 자</strong>: 부모님(직계존속)과 주민등록표등본상에 함께 등재되어 거주하는 경우예요. 흔히 독립하지 않고 부모님 댁에 거주하는 <a href="https://www.joongang.co.kr/article/25328304" target="_blank" rel="noreferrer"><strong>캥거루족</strong></a> 이 여기에 해당하며, 이 경우에는 <strong>전용면적 60㎡를 초과</strong> 하는 주택에도 신청이 가능해요.</li></ul><p>당시 저는 부모님과 함께 거주하고 있었기 때문에 <mark>단독세대가 아닌 자</mark> 로 분류되었어요. 덕분에 전용면적 60㎡ 초과 주택에도 신청할 수 있는 자격이 주어졌고, 모집공고 기준 가장 작은 면적이었던 70㎡ 주택형으로 청약을 신청할 수 있었답니다.</p><blockquote><p><strong>국민평형(84㎡)</strong> 으로 신청하지 않은 건 같이 살아갈 여자친구와 현재 <mark>모아놓은 자본과 소득에 따른 대출 가능성</mark> 을 고려해서 상의한 결정이었어요.</p></blockquote><h2 id="생애최초-특별공급-증빙-서류-준비하기" tabindex="-1">생애최초 특별공급 증빙 서류 준비하기 <a class="header-anchor" href="#생애최초-특별공급-증빙-서류-준비하기" aria-label="Permalink to “생애최초 특별공급 증빙 서류 준비하기”">​</a></h2><p>청약 당시에 저를 생각보다 힘들게 했던 생애최초 특별공급 증빙 서류에 대해서 알아볼게요.</p><h3 id="_1-5개년도-소득세-납부-증빙-연속-여부-상관없음" tabindex="-1">1. 5개년도 소득세 납부 증빙 (연속 여부 상관없음) <a class="header-anchor" href="#_1-5개년도-소득세-납부-증빙-연속-여부-상관없음" aria-label="Permalink to “1. 5개년도 소득세 납부 증빙 (연속 여부 상관없음)”">​</a></h3><p>생애최초 특별공급에 당첨되었다면 <strong>소득세 납부 사실</strong> 을 증빙할 수 있는 서류가 필요해요. 최근 5년 동안 한 직장에서 근무했다면 회사에 <strong>근로소득원천징수영수증</strong> 을 요청해 한 번에 발급받으면 되지만, 이직 이력이 있다면 홈택스에서 각 연도별 <strong>소득금액증명원</strong> 을 발급받는 것이 훨씬 수월해요. 이때 최근 5년이 <strong>연속될 필요는 없으며</strong>, <mark>평생 동안 소득세를 납부한 내역이 총 5개년도</mark> 라는 것만 증명하면 된답니다.</p><ul><li>근로소득원천징수영수증은 팩스나 복사본이 아닌 반드시 주민등록번호 뒷자리가 포함된 <strong>원본</strong> 으로 제출해야 해요.</li><li>저의 경우 재직 회사에서 발급해 준 원천징수영수증 일부가 직인 날인이 인쇄된 복사본이어서, 결국 <strong>소득금액증명원</strong> 으로 대체하여 제출했어요.</li></ul><h3 id="_2-부모님을-포함한-세대-구성원-자격-증빙" tabindex="-1">2. 부모님을 포함한 세대 구성원 자격 증빙 <a class="header-anchor" href="#_2-부모님을-포함한-세대-구성원-자격-증빙" aria-label="Permalink to “2. 부모님을 포함한 세대 구성원 자격 증빙”">​</a></h3><p>무주택세대구성원으로서 생애최초 특별공급에 당첨되었다면, 주민등록표등본에 기재된 <strong>형제자매를 제외한 모든 세대구성원 기준의</strong> 증빙 서류가 필요해요. 이에 따라 <strong>저를 포함해 직계존속인 아버지와 어머니에 대한 서류</strong> 를 발급받아 제출해야 했어요. 간이과세자이신 아버지는 사업자등록증 사본을 준비하셔야 했고, 근로자이신 어머니는 재직 중이신 회사에 (아파트 계약 증빙용) 재직증명서 발급을 요청해야 했답니다.</p><ul><li>직인 날인된 재직증명서 (또는 사업자등록증 사본)</li><li>과거 변동사항이 모두 기재된 <a href="https://www.gov.kr/portal/service/serviceInfo/PTR000050333" target="_blank" rel="noreferrer">건강보험자격득실확인서</a></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>세대 구성원의 재직증명서 역시 주민등록번호 뒷자리가 모두 표시되어야 하므로, 회사에 요청할 때 <strong>아파트 계약용</strong> 또는 <strong>주택공급 계약용</strong> 으로 발급을 신청해 주세요.</p></div><h3 id="_3-소득-및-자산-기준-증빙-서류" tabindex="-1">3. 소득 및 자산 기준 증빙 서류 <a class="header-anchor" href="#_3-소득-및-자산-기준-증빙-서류" aria-label="Permalink to “3. 소득 및 자산 기준 증빙 서류”">​</a></h3><p>청약 당첨 당시 세대원 합산 기준으로 소득 기준을 충족했다는 건 서류로 완벽히 증빙해야 해요. 저의 경우 부모님과 함께 등재되어 있었기 때문에 3인 가구 기준으로 <strong>세대 월평균 소득이 160% 이하(11,528,499원 이하)</strong> 임을 증빙해야 했는데요. 생애최초 특별공급 당첨자의 모든 세대 구성원은 자격 및 소득 검증을 위한 서류를 발급받아야 해요. 만약 입주자모집공고일이 7월 이전이라면 간이과세자의 전년도 소득금액증명 발급이 불가능하므로, <strong>전전년도 소득금액증명</strong> 을 발급받아 제출해야 해요.</p><ul><li>직인 날인된 재직증명서 또는 사업자등록증 사본</li><li>직인 날인된 전년도 근로소득원천징수영수증 또는 전년도(혹은 전전년도) 소득금액증명원</li><li>피부양 직계존속(아버지, 어머니)의 주민등록표 초본 (상세 내역 포함)</li></ul><p>소득 기준을 초과한 추첨제 신청자의 경우에도 모든 세대원의 <mark>부동산 자산가액 합계가 3억 3,100만 원 이하</mark> 임을 증명할 수 있으면 적격 처리가 돼요. 자산 기준을 증빙하기 위해 요구되는 서류들은 발급 절차가 다소 복잡한 편이에요. 근로자라면 근로소득원천징수영수증상 총급여액을, 간이과세자라면 소득금액증명원의 소득금액을 12로 나누어 월평균 소득을 산출한 뒤 모든 세대원의 소득을 합산하면 돼요.</p><blockquote><p>서류 검증 시 검수자의 도움을 받아 직접 확인해 보니 저희 세대는 약 700만 원 선이었어요. 미리 계산해 본 소득 기준이 잘못되었을까 봐 조금 불안하기도 했지만, 다행히 안전하게 적격 기준을 충족하여 별도의 서류 보완 요청 없이 무사히 아파트 공급 계약을 체결할 수 있었답니다.</p></blockquote><h2 id="서류-심사-통과-후-정당-계약일에-준비한-것들" tabindex="-1">서류 심사 통과 후 정당 계약일에 준비한 것들 <a class="header-anchor" href="#서류-심사-통과-후-정당-계약일에-준비한-것들" aria-label="Permalink to “서류 심사 통과 후 정당 계약일에 준비한 것들”">​</a></h2><p>당첨 이후 정해진 기간 내에 아파트 공급계약을 체결하는 것을 <strong>정당 계약</strong> 이라고 부르더라고요. 서류 심사가 무사히 통과되고 적격 판정을 받으면 접수 확인증을 주는데, 정당 계약일에 아래의 서류들을 지참하여 견본주택(모델하우스)에 방문하도록 안내받았어요.</p><ul><li>신분증 사본 (견본주택에서 현장 복사 가능)</li><li>공통 및 생애최초 특별공급 자격검증서류 접수 확인증</li><li>본인서명사실확인서 또는 인감증명서 (아파트 계약용)</li><li>분양대금 및 발코니 확장 공사비 무통장 입금 영수증</li><li>인지세 납부를 위한 종이문서용 전자수입인지</li></ul><p>서류 제출 시 인감증명서를 함께 제출했다면, 계약 당일에는 인감도장만 지참하시면 돼요. <mark>분양대금 납부 계좌와 발코니 확장비 납부 계좌가 서로 다르므로</mark> 송금 시 반드시 확인해야 해요. 인지세의 경우, 계약 체결 후 공급계약서를 수령하고 나서 우체국이나 인터넷을 통해 전자수입인지를 구매해 첨부하면 돼요.</p><p>정식 계약 안내문에 적힌 준비사항과 다르게, 실제 현장에서는 굳이 직접 챙기지 않거나 꼼꼼히 확인하지 않는 것들도 꽤 있었어요. 신분증 사본의 경우 따로 복사해 갈 필요 없이 견본주택(모델하우스)에 가면 알아서 다 복사해 주시더라고요. 무통장 입금 영수증 지참도 필수라고 안내되어 있었지만, 현장에서는 따로 영수증 실물을 까다롭게 대조하기보다는 시스템에 수납된 정보를 토대로 수월하게 확인하여 계약서에 첨부해 주셨어요. 또한 에어컨 등의 유상 옵션 계약은 정당 계약일에 함께 진행하지 않고, 추후 중도금 대출자서(대출 계약서 서명)일에 같은 날 진행했어요. 이는 시행사마다 일정이 조금씩 다른 것 같은데, 제가 분양받은 단지는 <a href="http://jeil-yj.co.kr/in.pdf?n=2" target="_blank" rel="noreferrer">중도금 대출자서 및 유상옵션 계약 안내문</a>을 통해 유상 옵션 계약에 대해 향후 추가 계약 일정이 아예 없다고 사전에 안내받았기 때문에 필수적으로 일정을 챙겨야 했답니다. 이 주택의 경우 계약금은 분양대금의 5%였고, <strong>1차 계약금 500만 원</strong> 을 먼저 납부한 뒤 나머지 잔여 계약금은 계약일로부터 30일 이내에 지정된 계좌로 입금하도록 되어 있었어요.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>계약금 입금이 일부 지연되더라도 즉시 계약이 해지되지는 않지만, <strong>연 15% 수준의 높은 연체 이자</strong> 가 발생해요. 또한 계약 체결 이후 마음이 바뀌어 계약을 취소(해제)할 경우 분양대금의 <strong>위약금 기준(10%)</strong> 이 발생하는데요. 이 공고의 경우 계약금이 분양대금의 5%였기 때문에, 계약을 취소하려면 이미 납부한 계약금 외에 위약금 기준(10%)을 맞추기 위해 추가로 <mark>500만 원 정도를 더 납부</mark> 해야 한다는 무서운 사실을 안내받았어요.</p></div><h2 id="무이자-중도금-대출이라도-들어가는-실제-비용" tabindex="-1">무이자 중도금 대출이라도 들어가는 실제 비용 <a class="header-anchor" href="#무이자-중도금-대출이라도-들어가는-실제-비용" aria-label="Permalink to “무이자 중도금 대출이라도 들어가는 실제 비용”">​</a></h2><p>계약 체결 이후, 중도금 1차 납부일 전에 협약 은행 지정 안내 문자를 받고 집단 중도금 대출을 신청했어요. 이번 공고는 <strong>중도금 60% 전체</strong> 에 대하여 중도금 대출 무이자 조건이었지만, <mark>대출에 대한 보증료만큼은 개인이 직접 납부</mark> 해야 하는 비용이에요. 바로 <a href="https://www.khug.or.kr/hug/web/ig/hp/ighp000001.jsp" target="_blank" rel="noreferrer">주택구입자금보증</a> 수수료인 대출금의 연 0.13%에 해당하는 보증료와 대출 인지세였답니다.</p><ul><li>정당 계약 시의 납부 계좌와 다르게, 중도금 대출이 실행되면 은행에서 대출 전용 계좌를 통해 직접 상환 및 납부가 이루어져요.</li><li>사업주체가 이자를 대납해 주는 무이자 대출 조건인 경우, 연말정산 시 <a href="https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?mi=40608&amp;cntntsId=239020" target="_blank" rel="noreferrer">장기주택저당차입금 이자상환액 소득공제</a> <mark>혜택은 적용받을 수 없어요</mark>.</li></ul><h2 id="잔금대출-계획과-입주-시점의-현실적인-규제-고민" tabindex="-1">잔금대출 계획과 입주 시점의 현실적인 규제 고민 <a class="header-anchor" href="#잔금대출-계획과-입주-시점의-현실적인-규제-고민" aria-label="Permalink to “잔금대출 계획과 입주 시점의 현실적인 규제 고민”">​</a></h2><p>입주 시기가 다가올 때 정부 정책에 따라 대출 가능액이 언제든지 변동될 수 있으므로, 지금은 현실적으로 입주 시점에 반드시 받아야 하는 필요 금액을 보수적으로 산정해 두는 것이 좋아요. 특히 주택담보대출의 경우 개인 소득에 따른 <strong>DSR 3단계 규제</strong> 가 적용되어 대출 한도가 크게 제한될 수 있거든요. 게다가 현재 <a href="https://www.hf.go.kr/ko/sub01/sub01_02_01.do#" target="_blank" rel="noreferrer">디딤돌대출</a> 같은 정부 저금리 대출의 경우, <strong>후취담보 취급 금지</strong> 정책으로 인해 <mark>소유권 등기가 없는 신축 아파트</mark> 는 대출 신청 및 실행이 원칙적으로 불가능해요. 이 때문에 향후 입주예정자협의회 등을 통해 협약된 일반 은행의 후취담보 집단대출을 먼저 이용해야 할 수도 있어요. <a href="https://www.hf.go.kr/ko/sub02/sub02_02_06.do" target="_blank" rel="noreferrer">생애최초 특례구입자금보증</a>을 통해 담보주택 가격의 LTV 80%까지 대출 한도가 나오는지, 그리고 등기가 아직 없는 신축 아파트에 대해서도 보증이 가능한지 아직 확실치 않아 추후 자세히 알아보려고 해요. 저의 경우 당장은 실제로 입주하여 거주하려는 <strong>실수요자</strong> 이기 때문에, 대출 부족 시 대안으로 언급되는 &#39;전세 세입자를 들여 잔금을 치르는 방식&#39;은 대응 방안이 될 수 없답니다.</p><h2 id="주택-소유권-이전-시-들어가는-부대비용-정리" tabindex="-1">주택 소유권 이전 시 들어가는 부대비용 정리 <a class="header-anchor" href="#주택-소유권-이전-시-들어가는-부대비용-정리" aria-label="Permalink to “주택 소유권 이전 시 들어가는 부대비용 정리”">​</a></h2><p>중도금 6회차 납부가 끝나고 입주 예정일이 다가오면, 잔금 납부와 함께 대출 상환뿐만 아니라 다양한 <strong>부대비용</strong> 들이 추가로 발생하게 돼요. 생각보다 챙겨야 할 예산이 많으므로 미리 확인하고 준비해 두는 것이 좋아요.</p><ol><li><strong>취득세와 지방교육세</strong>: 분양가에 발코니 확장비, 유상 옵션을 모두 합산한 실제 취득가액을 기준으로 <strong>취득세 1%와 지방교육세 0.1%</strong> 가 부과돼요. (다행히 전용면적 85㎡ 이하의 주택이라 <strong>농어촌특별세는 비과세 대상</strong> 이에요.)</li><li><strong>국민주택채권 매입 비용</strong>: 소유권 이전 등기를 진행할 때 법적으로 매입해야 하는 채권으로, 보통 <strong>즉시 할인 매각</strong> 하여 발생하는 차액만큼 현금 비용을 부담해요.</li><li><strong>등기 및 법무사 비용</strong>: 소유권 이전을 위한 등기 수수료(증지대, 인지세 등)와 대행 <strong>법무사 수수료</strong> 가 발생해요.</li><li><strong>대출 실행 부대비용</strong>: 잔금대출 실행 시 <strong>채권 설정 비용</strong> 과 인지세 등의 추가 수수료가 발생할 수 있어요.</li></ol><p>상세한 등기 관련 부대비용은 <a href="https://xn--989a00af8jnslv3dba.com/%EB%93%B1%EA%B8%B0%EB%B9%84%EC%9A%A9" target="_blank" rel="noreferrer">부동산 계산기</a>를 통해 대략적으로 시뮬레이션해 볼 수 있답니다.</p><h3 id="취득세-감면-혜택과-3년-실거주-의무-고민" tabindex="-1">취득세 감면 혜택과 3년 실거주 의무 고민 <a class="header-anchor" href="#취득세-감면-혜택과-3년-실거주-의무-고민" aria-label="Permalink to “취득세 감면 혜택과 3년 실거주 의무 고민”">​</a></h3><p>제가 청약한 단지는 원래 실거주 의무가 전혀 없는 조건이에요. 하지만 생애최초 주택 구입자에게 주어지는 <a href="https://www.banksalad.com/articles/25%EB%85%84-%EC%83%9D%EC%95%A0%EC%B5%9C%EC%B4%88-%EC%A3%BC%ED%83%9D-%EC%B7%A8%EB%93%9D%EC%84%B8-%EA%B0%90%EB%A9%B4-%ED%98%9C%ED%83%9D-%EC%B4%9D%EC%A0%95%EB%A6%AC" target="_blank" rel="noreferrer">취득세 감면 혜택</a>을 지자체로부터 받게 되면, 혜택 적용 요건에 의해 <strong>3년 동안의 실거주 의무</strong> 가 추가로 발생하게 된답니다.</p><p>아직까지 저는 실제로 입주해서 거주할 생각이기 때문에 이 취득세 감면 혜택을 받는 방향으로 고려하고 있어요. 설령 혜택을 받고 <mark>나중에 사정이 생겨 3년 내에 매매를 하게 되더라도</mark>, 감면받았던 취득세와 일부 가산세에 대한 리스크만 감수하면 되기 때문이에요.</p><p>감사합니다.</p>`,53)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};